export type CanonicalJobCategory =
 | 'tech'
 | 'finance'
 | 'health'
 | 'engineering'
 | 'admin'
 | 'hospitality'
 | 'sales'
 | 'other';

export type CanonicalContractType = 'full-time' | 'part-time' | 'temporary' | 'internship' | 'contract';

// Self-hosted logo paths under /public/images/brands/. Generated by
// scripts/download-company-logos.mjs and overlaid onto the registry below
// so every lookup serves a local file (no Clearbit / Google-favicon flakiness).
// Relative path (not `@/data/...`) so this resolves under Node when build
// plugins import it without the Vite path-alias resolver kicking in.
import COMPANY_LOGOS_MANIFEST from '../data/company-logos-manifest.json';

type JobLike = {
 company?: string;
 companyKey?: string;
 companyDomain?: string;
 url?: string;
 /** Publisher-provided logo URL (projected from the publish form, https-only). */
 companyLogo?: string | null;
};

