/**
 * Patterns that indicate a job location is non-geographic (multi-location / abroad /
 * "depending on function"). These strings should be normalised in the UI rather than
 * displayed verbatim as if they were a city or canton.
 *
 * The regex is intentionally broad enough to cover German, French, and Italian
 * variants that appear in Swiss federal job portals.
 */
const MULTI_LOCATION_PATTERNS = /\b(in\s*?-?\s*?und\s+ausland|schweiz\s+und\s+ausland|suisse\s+et\s+(?:l.)?étranger|svizzera\s+e\s+(?:l.)?estero|abhängig\s+von\s+funktion|einsatzort|verschiedene\s+standorte|multiple\s+locations?|several\s+locations?|ganz\s+schweiz|toute\s+la\s+suisse)\b/i;

/**
 * Returns whether a raw `location` value represents a non-geographic description
 * (e.g. "Schweiz und Ausland (abhängig von Funktion und Einsatzort)") rather than
 * a concrete city or region. When true, callers should display a locale-appropriate
 * neutral label instead of the raw string.
 */
export function isMultiLocation(location: unknown): boolean {
 if (!location) return false;
 return MULTI_LOCATION_PATTERNS.test(String(location));
}

export function resolveCompanyWebsiteHost(job: JobLike): string {
 const explicitHost = toBaseDomain(job.companyDomain || '');
 const urlHost = hostFromExternalUrl(job.url);

 if (isMedacta(job)) return 'medacta.com';
 if (isVf(job)) return 'vfc.com';
 if (isEfg(job)) return 'efginternational.com';
 if (isDelvitech(job)) return 'delvi.tech';
 if (isFincons(job)) return 'finconsgroup.com';
 if (isConvit(job)) return 'convit.ch';
 if (isGoline(job)) return 'goline.ch';
 if (isLivingCircle(job)) return 'thelivingcircle.ch';
 if (isBracco(job)) return 'bracco.com';
 if (isBoggi(job)) return 'boggi.com';
 if (isSwisscom(job)) return 'swisscom.ch';
 if (isSunrise(job)) return 'sunrise.ch';
 if (isAriston(job)) return 'aristongroup.com';
 if (isBosch(job)) return 'bosch.ch';
 if (isRittmeyer(job)) return 'rittmeyer.com';
 if (isLinea(job)) return 'linea.ch';
 if (isUsi(job)) return 'irsol.usi.ch';
 if (normalizeCompanyIdentity(`${job.company || ''} ${job.companyKey || ''}`).includes('posta svizzera')
 || normalizeCompanyIdentity(`${job.company || ''} ${job.companyKey || ''}`).includes('post ch')
 || normalizeCompanyIdentity(`${job.company || ''} ${job.companyKey || ''}`).includes('posta-svizzera-centro-regionale')) {
 return 'post.ch';
 }
 if (isAmministrazioneCantonaleTi(job)) return 'ti.ch';

 if (explicitHost && !isAtsHost(explicitHost)) return explicitHost;
 if (urlHost && !isAtsHost(urlHost)) return urlHost;

 if (explicitHost) return explicitHost;
 if (urlHost) return urlHost;
 return '';
}

export function resolveCompanyLogoUrl(job: JobLike): string | null {
 // 0. Publisher-provided logo (projected from the publish form; validated
 // https-only at projection time). Only publisher-submitted records carry
 // this field, so behavior for crawled jobs is unchanged.
 const ownLogo = String(job.companyLogo || '').trim();
 if (/^https:\/\/\S+$/i.test(ownLogo)) return ownLogo;

 // 1. Explicit crawled-company logo map (most reliable)
 const key = job.companyKey || '';
 if (key && CRAWLED_COMPANY_LOGOS[key]) {
 return CRAWLED_COMPANY_LOGOS[key];
 }

 // 2. Identity-based fallbacks for variant company names / keys
 if (isMedacta(job)) return CRAWLED_COMPANY_LOGOS['medacta-international'];
 if (isVf(job)) return CRAWLED_COMPANY_LOGOS['vf-international-the-north-face-timberland'];
 if (isEfg(job)) return CRAWLED_COMPANY_LOGOS['efg-international'];
 if (isDelvitech(job)) return CRAWLED_COMPANY_LOGOS['delvitech-sa'];
 if (isFincons(job)) return CRAWLED_COMPANY_LOGOS['fincons-group'];
 if (isConvit(job)) return CRAWLED_COMPANY_LOGOS['convit-holding'];
 if (isGoline(job)) return CRAWLED_COMPANY_LOGOS['goline'];
 if (isLivingCircle(job)) return CRAWLED_COMPANY_LOGOS['the-living-circle'];
 if (isBracco(job)) return CRAWLED_COMPANY_LOGOS['bracco'];
 if (isBoggi(job)) return CRAWLED_COMPANY_LOGOS['boggi-milano'];
 if (isSwisscom(job)) return CRAWLED_COMPANY_LOGOS['swisscom-sede-ticino'];
 if (isAriston(job)) return CRAWLED_COMPANY_LOGOS['ariston-group'];
 if (isBosch(job)) return CRAWLED_COMPANY_LOGOS['bosch-thermotechnik-ag'];
 if (isRittmeyer(job)) return CRAWLED_COMPANY_LOGOS['rittmeyer-ag'];
 if (isUsi(job)) return CRAWLED_COMPANY_LOGOS['usi-universita-della-svizzera-italiana'];
 if (normalizeCompanyIdentity(`${job.company || ''} ${job.companyKey || ''}`).includes('posta svizzera')
 || normalizeCompanyIdentity(`${job.company || ''} ${job.companyKey || ''}`).includes('post ch')
 || normalizeCompanyIdentity(`${job.company || ''} ${job.companyKey || ''}`).includes('posta-svizzera-centro-regionale')) {
 return CRAWLED_COMPANY_LOGOS['posta-svizzera-centro-regionale'];
 }

 // 3. No curated logo and no identity match. We deliberately do NOT fall back
 // to gFavicon(host) here: Google's favicon API serves a generic grey-globe
 // PNG (HTTP 200/404-with-body, ~726 B) for domains it can't resolve, which
 // browsers render even on a 404 — so the <img onError> chain never fires and
 // the user sees the broken-looking grey globe (e.g. crawled companies on ATS
 // sub-domains like duferco.talentics.ai). Returning null lets the SPA and the
 // static SEO renderer fall through to the deterministic coloured-initials
 // badge instead — a real visual identity, never the grey globe.
 return null;
}

/**
 * Maximum length for a job slug segment within a URL path.
 *
 * Rationale: Semrush A9 (Issue 201) flags URLs >200 characters as a
 * structural SEO problem. Job page URLs use the pattern
 *   /{lang-prefix}/{section-slug}/{job-slug}/
 * where the path overhead (locale prefix + section-slug + leading and
 * trailing slashes) consumes ~20 characters. A 180-character cap on the
 * job-slug segment leaves a comfortable margin so the full URL stays
 * under 200 characters even when the locale-specific section slug is
 * the longest variant ("offerte-di-lavoro" / "stellenangebote").
 *
 * 180 is also wider than the 90-character cap used inside
 * `build-plugins/jobsSeoPagesPlugin.ts` for newly-derived fallback
 * slugs, so it does NOT change behavior for the vast majority of
 * existing slugs (which are 30-90 chars). It only kicks in for the few
 * pathological multi-locale auto-generated slugs that exceeded 180.
 *
 * Truncation appends a 6-character deterministic hash suffix to keep
 * the truncated form unique whenever two long inputs would otherwise
 * collapse to the same prefix. Using a stable hash (not a random one)
 * means rebuilding the same input always produces the same short slug,
 * preserving the canonical URL across deploys.
 */
export const MAX_JOB_SLUG_LENGTH = 180;

/**
 * Returns a small deterministic hex hash of `input`. Implementation is a
 * 32-bit FNV-1a fold rendered as 6 lowercase hex chars. Good enough for
 * slug disambiguation collisions (1 in ~16M, far below the volume of
 * over-long slugs we observe). Independent of Node's `crypto` module so
 * it works in any runtime that imports this file (including the Vite
 * browser bundle via the SPA → router code path).
 */
function shortHash6(input: string): string {
 let h = 0x811c9dc5;
 for (let i = 0; i < input.length; i += 1) {
 h ^= input.charCodeAt(i);
 h = Math.imul(h, 0x01000193);
 }
 // Ensure unsigned, then 24-bit truncate so we can render exactly 6 hex chars.
 const u = (h >>> 0) & 0x00ffffff;
 return u.toString(16).padStart(6, '0');
}

/**
 * Truncate a job slug to {@link MAX_JOB_SLUG_LENGTH} characters, appending
 * a 6-char deterministic hash suffix (separated by `-`) when truncation
 * occurs so the result remains unique. Slugs already at or below the
 * limit are returned untouched (no mutation).
 *
 * The function is idempotent and runtime-only: it does not mutate any
 * stored data — callers must persist the returned value back into the
 * job record (or use it at URL-emit time) for it to take effect.
 *
 * Usage: invoke when emitting `<job-slug>` segments into URLs (e.g.
 * inside `build-plugins/jobsSeoPagesPlugin.ts` `localizedSlug`,
 * `services/router.ts` job-detail path builder, or any crawler script
 * that writes `job.slug` / `job.slugByLocale[locale]`).
 */
export function truncateJobSlug(rawSlug: string): string {
 const slug = String(rawSlug || '').trim();
 if (!slug) return '';
 if (slug.length <= MAX_JOB_SLUG_LENGTH) return slug;
 const suffix = `-${shortHash6(slug)}`;
 // 6 hash chars + 1 hyphen = 7 characters reserved for disambiguation.
 const headLen = MAX_JOB_SLUG_LENGTH - suffix.length;
 // Trim a trailing partial-word hyphen so the result reads cleanly:
 //   "very-long-...-trun" + "-abc123"   not   "very-long-...-trun-" + "-abc123".
 const head = slug.slice(0, headLen).replace(/-+$/, '');
 return `${head}${suffix}`;
}
